export DOVE_OSX_INTEL_ONLY
if [[ "${DOVE_OSX_INTEL_ONLY}" == 1 ]]; then
  DOVE_OSX_INTEL=1
  DOVE_LINUX=0
  DOVE_LINUX_FLATPAK=0
